    expect(sympyStr(together(new Add([Rational.of(1n, 1n, { gcd: 1n }), new Mul([new Pow(x, Rational.of(-1n, 1n, { gcd: 1n })), new Pow(new Add([Rational.of(1n, 1n, { gcd: 1n }), x]), Rational.of(-1n, 1n, { gcd: 1n }))])]), { deep: false }))).toBe('(x*(x + 1) + 1)/(x*(x + 1))');
